"""Hand-authored visual explanations, keyed by stable page class names.

These are small teaching examples, not replacements for the numerical labs.
Class keys deliberately avoid the stale page numbers in older lesson prose.
"""
from dataclasses import dataclass, field
from functools import lru_cache


@dataclass(frozen=True)
class Step:
    title: str
    caption: str
    data: dict = field(default_factory=dict)


@dataclass(frozen=True)
class Story:
    title: str
    scene: str
    steps: tuple[Step, ...]
    nodes: tuple[str, ...] = ()
    seconds: float = 6.0


def S(title, caption, **data):
    return Step(title, caption, data)


def movie(title, scene, *steps, nodes=(), seconds=6.0):
    return Story(title, scene, steps, nodes, seconds)


@lru_cache(maxsize=1)
def deterministic_sweeps():
    """Real Bellman updates for the reward-wave movie; no invented heat map."""
    from rlcore.frozen_lake import build_model
    from rlcore.dp import q_from_V
    model = build_model("deterministic", "gym")
    history = [[0.0]*16]
    for _ in range(8):
        old = history[-1]
        history.append([max(q_from_V(model, old, s, a, .9) for a in range(4)) for s in range(16)])
    return history


