        S("Do that for every candidate action", "The inner computation produces an action value for each action. Now the weights change from transition probabilities to policy probabilities.", root="Vπ(s)", values=(.425, .6, .2), weights=(.2, .5, .3), branch="Qπ", equation="Outer weights are π(a|s), not P(s′|s,a)."),
