        S("Choose the highest score", "Greedy improvement changes the selected action to the highest Qπ value. Under exact evaluation this cannot reduce the policy's value.", root="New action", values=(.2, .6, .4), reduce="max", branch="Qπ", equation="New policy chooses action 2, whose lookahead score is 0.6."),
